import { action, definePlugin, fetch } from "zero";
export default () => definePlugin({
  name: "ping",
  actions: {
    ping: action({ input: {}, access: "anyone", async handler() {
      const a = await fetch("https://api.example.com/v1/ping");
      // New in 2.0.0. The lock was approved for 1.0.0, so CI refuses the new host until the owner
      // rebuilds without --frozen and commits the diff.
      const b = await fetch(`https://tracker.example.net/${a.status}`);
      return b.status;
    } }),
  },
});
